    public static TimedRelation[] Offices(ContractWorld w,TimedRelation[] initial){if(!Enabled(w))return initial;var list=initial.ToList();foreach(var j in Jobs(w).Where(j=>j.Applied!=null).OrderBy(j=>j.Applied!.Revision)){var e=j.Applied!;var t=j.Terms;int i=list.FindIndex(o=>o.Subject==t.Incumbent&&o.Target==t.Home&&o.Kind=="house-head"&&o.Until==long.MaxValue);Need(i>=0&&e.At>list[i].From,"旧当主職と有効な交代時刻がありません");list[i]=list[i] with{Until=e.At,Revision=e.Revision};list.Add(new(new("office:house-succession/"+ContractJson.Hash(System.Text.Encoding.UTF8.GetBytes(e.Input.Id.Value))),t.Heir,t.Home,"house-head",NewGameWorld.Basis,e.At,long.MaxValue,e.Revision));}return list.ToArray();}
    internal static void Sync(ContractWorld w){if(Enabled(w))w.Offices=Offices(w,NewGameWorld.InitialRelations(w.NewGame!).Offices);}
    public static HouseSuccessionEntry? Acknowledged(ContractWorld w,EntityId original,EntityId owner,long at,long rev)=>Enabled(w)?Entries(w,at,rev).LastOrDefault(e=>e.Input.Action==HouseSuccessionAction.Acknowledge&&e.Input.Original==original&&e.Input.Owner==owner&&e.Representative==Head(w,owner,at,rev)):null;
    internal static EntityId SettlementPrincipal(ContractWorld w,EntityId original,EntityId owner,EntityId principal,long at,long rev){if(!Enabled(w)||Head(w,owner,at,rev)==principal)return principal;var acknowledged=Acknowledged(w,original,owner,at,rev);Need(acknowledged!=null,"現当主と元の当事者による個別原本の確認を待っています");return acknowledged.Representative!.Value;}
    static HouseSuccessionObligation Obligation(ContractWorld w,EntityId id,long at,long rev){var salary=HouseSalary.SnapshotAt(w,at,rev).Terms.SingleOrDefault(t=>t.Id==id);if(salary!=null){long owed=salary.Monthly*salary.DueAt.LongCount(d=>d<=at&&(salary.EndedAt==null||d<=salary.EndedAt))-salary.Paid;Need(owed>0||salary.EndedAt==null&&at<salary.DueAt[^1],"精算済みの給付契約です");return new(id,salary.Owner,salary.Site,salary.Employer,salary.Employee,"salary",owed);}var freight=HouseLogistics.FreightJobs(w,at,rev).SingleOrDefault(j=>j.Terms.Id==id);Need(freight!=null&&freight.Phase is not(HouseFreightPhase.Completed or HouseFreightPhase.Returned),"未精算の給付または運搬原本を指定してください");var f=freight.Terms;return new(id,f.Owner,f.Home,f.Principal,f.Carrier,"freight",freight.Cargo);}
    static HouseSuccessionEntry Prepare(ContractWorld w,HouseSuccessionInput i,long at,long rev,bool automatic=false)
    {
        Need(Enabled(w)&&Enum.IsDefined(i.Action)&&EntityId.IsValid(i.Id.Value)&&w.NewGame!.Start.Factions.Any(f=>f.Id==i.Owner.Value),"当主交代の入力が不正です");long before=rev-1;
        if(i.Action==HouseSuccessionAction.Nominate){Need(!automatic&&i.Person is {}&&i.Original==null&&!Jobs(w,at,before).Any(j=>j.Pending!=null||j.Cancelled==null&&j.Applied==null&&at<=j.Terms.Until),"先の交代合意を終えてから候補を選んでください");var old=Head(w,i.Owner,at,before);var heir=i.Person!.Value;var home=new EntityId(w.NewGame!.Start.Factions.Single(f=>f.Id==i.Owner.Value).Home);Need(old!=heir&&(w.PlayerControl==old||w.PlayerControl==heir)&&w.Characters.SingleOrDefault(c=>c.Id==heir)?.Life==LifeState.Adult&&Member(w,heir,i.Owner,at,before)&&Direct(w,heir,old,at,before)&&!Factions(w,at,before).Any(f=>f.Head==heir.Value),"同じ家の成人直属家臣と当主の当事者が必要です");Need(Local(w,old,home,at,before)&&Local(w,heir,home,at,before)&&!PersonalLife.Resting(w,at,before)&&!CastleAdministration.Blocked(w,home,at,before)&&FactionStances.ResolveAuthority(w,old,i.Owner,at,Math.Min(before,w.CommitSequence))!=null,"当事者の現地立会いと当主職の実権が必要です");var other=w.PlayerControl==old?heir:old;var t=new HouseSuccessionTerms(i.Id,i.Owner,old,heir,home,checked(at+86400),w.Characters.Single(c=>c.Id==other).WillObey);return new(i,at,rev,t,null,null,null,null,null);}
        if(i.Action==HouseSuccessionAction.Acknowledge){Need(!automatic&&i.Person==null&&i.Original is {},"個別の原本を指定してください");var o=Obligation(w,i.Original!.Value,at,before);var head=Head(w,o.Owner,at,before);Need(o.Owner==i.Owner&&o.OriginalPrincipal!=head&&(w.PlayerControl==head||w.PlayerControl==o.Counterparty)&&Acknowledged(w,o.Id,o.Owner,at,before)==null,"現当主と当事者が元の家の原本を個別確認してください");Need(Local(w,head,o.Site,at,before)&&Local(w,o.Counterparty,o.Site,at,before)&&!PersonalLife.Resting(w,at,before)&&!CastleAdministration.Blocked(w,o.Site,at,before)&&FactionStances.ResolveAuthority(w,head,o.Owner,at,Math.Min(before,w.CommitSequence))!=null,"原本の受渡先で当事者と権限を確認してください");var other=w.PlayerControl==head?o.Counterparty:head;Need(other==w.PlayerControl||w.Characters.Single(c=>c.Id==other).WillObey,"相手がこの原本の引継ぎに同意しません");return new(i,at,rev,null,null,null,head,o.Counterparty,o.Kind);}
        Need(i.Person==null&&i.Original is {},"同じ交代合意を指定してください");var job=Jobs(w,at,before).Single(j=>j.Terms.Id==i.Original&&j.Terms.Owner==i.Owner);var terms=job.Terms;Need(job.Cancelled==null&&job.Applied==null,"既に終了した交代原本です");
        if(i.Action==HouseSuccessionAction.Resolve){Need(automatic&&job.Pending?.Due==at&&i.Id==ResolutionId(job.Pending),"予定した交代境界ではありません");return new(i,at,rev,null,null,Outcome(w,terms,at,before),null,null,null);}
        Need(!automatic&&(w.PlayerControl==terms.Incumbent||w.PlayerControl==terms.Heir)&&Local(w,w.PlayerControl,terms.Home,at,before)&&!PersonalLife.Resting(w,at,before),"現地の当事者本人が確認してください");
        if(i.Action==HouseSuccessionAction.Cancel)return new(i,at,rev,null,null,null,null,null,null);
        Need(i.Action==HouseSuccessionAction.Confirm&&job.Pending==null&&terms.Agreed&&Outcome(w,terms,at,before)=="confirmed","同意・所在・権限・軍務の条件を再確認してください");return new(i,at,rev,null,checked(at+1),null,null,null,null);
    }
    static EntityId ResolutionId(HouseSuccessionEntry e)=>new("decision:house-succession/"+ContractJson.Hash(System.Text.Encoding.UTF8.GetBytes(e.Input.Id.Value)));
    public static HouseSuccessionView? ViewForProjection(ContractWorld w)=>View(w,false);
    internal static HouseSuccessionView? View(ContractWorld w,bool obligations=true)
    {
        if(!Enabled(w))return null;long at=w.ElapsedSeconds,rev=w.CommitSequence;var loc=w.Locations.Single(l=>l.Actor==w.PlayerControl).Site;bool stable=loc is {} site&&Local(w,w.PlayerControl,site,at,rev+1);bool resting=PersonalLife.Resting(w,at,rev+1);var candidates=new List<HouseSuccessionCandidate>();
        if(stable&&!resting&&!Jobs(w).Any(j=>j.Pending!=null||j.Applied==null&&j.Cancelled==null&&at<=j.Terms.Until))foreach(var f in Factions(w)){var owner=new EntityId(f.Id);var head=new EntityId(f.Head);var home=new EntityId(f.Home);if(loc!=home||!Local(w,head,home,at,rev+1)||CastleAdministration.Blocked(w,home,at,rev+1))continue;foreach(var heir in w.Characters.Where(c=>c.Id!=head&&c.Life==LifeState.Adult).Select(c=>c.Id)){if((w.PlayerControl==head||w.PlayerControl==heir)&&Member(w,heir,owner,at,rev+1)&&Direct(w,heir,head,at,rev+1)&&Local(w,heir,home,at,rev+1)&&!Factions(w).Any(x=>x.Head==heir.Value))candidates.Add(new(owner,heir,home));}}
        var cards=Jobs(w).Select(j=>{var t=j.Terms;bool here=stable&&loc==t.Home;bool witnessed=j.Resolution!=null&&Local(w,w.PlayerControl,t.Home,j.Resolution.At,j.Resolution.Revision);string status=j.Cancelled!=null?"交代を取りやめ":j.Applied!=null?"生前合意による当主職交代を立会確認":j.Pending!=null?"次の時刻に当主職の交代を予定":j.Resolution!=null?(here||witnessed?"現地条件が整わず交代保留":"交代予定・結果は現地確認待ち"):at>t.Until?"確認期限を終了":t.Agreed?"当事者の同意あり・職の引渡し前":"相手はこの交代に不承諾";bool can=here&&!resting&&j.Applied==null&&j.Cancelled==null;return new HouseSuccessionCard(t.Id,t.Owner,t.Incumbent,t.Heir,t.Home,Entries(w,long.MaxValue,long.MaxValue).Single(e=>e.Input.Id==t.Id).At,j.Applied?.At,status,here,can&&j.Pending==null&&t.Agreed&&Outcome(w,t,at,rev)=="confirmed",can);}).ToArray();
        var result=new List<HouseObligationCard>();if(obligations){var ids=w.Salary!.Terms.Select(t=>t.Id).Concat(HouseLogistics.FreightJobs(w,at,rev+1).Select(j=>j.Terms.Id));foreach(var id in ids){HouseSuccessionObligation o;try{o=Obligation(w,id,at,rev);}catch(InvalidDataException){continue;}var head=Head(w,o.Owner);if(o.OriginalPrincipal==head||w.PlayerControl!=head&&w.PlayerControl!=o.Counterparty)continue;bool here=stable&&loc==o.Site;var ack=Acknowledged(w,id,o.Owner,at,rev);bool both=here&&Local(w,head,o.Site,at,rev+1)&&Local(w,o.Counterparty,o.Site,at,rev+1);result.Add(new(id,o.Owner,o.Site,o.OriginalPrincipal,o.Counterparty,o.Kind,both?o.Outstanding:null,both&&!resting&&ack==null&&!CastleAdministration.Blocked(w,o.Site,at,rev+1),ack!=null));}}
        return new(stable?loc:null,candidates.ToArray(),cards,result.ToArray());
    }
    internal static string? Role(ContractWorld w){if(!Enabled(w))return null;var jobs=Jobs(w).Where(j=>j.Applied!=null&&(j.Terms.Heir==w.PlayerControl||j.Terms.Incumbent==w.PlayerControl)).ToArray();if(jobs.Length==0)return null;return jobs.Any(j=>Head(w,j.Terms.Owner)==w.PlayerControl)?"当主（個人の奉公・指揮は別の原本）":"隠居（個人の約束と家の義務は別）";}
    internal static void Initialize(ContractWorld w){if(Enabled(w))w.Succession=new(1,Policy,[]);}
    internal static void Apply(ContractWorld w,HouseSuccessionInput i){var e=Prepare(w,i,w.ElapsedSeconds,w.CommitSequence);w.Succession=w.Succession! with{Entries=[..w.Succession.Entries,e]};Sync(w);}
    internal static void Tick(ContractWorld w){if(!Enabled(w))return;var j=Jobs(w).FirstOrDefault(j=>j.Cancelled==null&&j.Pending?.Due==w.ElapsedSeconds);if(j==null)return;var input=new HouseSuccessionInput(ResolutionId(j.Pending!),HouseSuccessionAction.Resolve,j.Terms.Owner,Original:j.Terms.Id);var e=Prepare(w,input,w.ElapsedSeconds,w.CommitSequence,true);w.Succession=w.Succession! with{Entries=[..w.Succession.Entries,e]};Sync(w);}
    internal static long? NextBoundary(ContractWorld w,long target)=>Jobs(w).Where(j=>j.Cancelled==null).Select(j=>j.Pending?.Due).Where(t=>t>w.ElapsedSeconds&&t<=target).Order().FirstOrDefault();
    internal static void Validate(ContractWorld w){if(!Enabled(w)){Need(w.Succession==null,"旧版へ当主交代を追加できません");return;}Need(w.Succession is {Schema:1,Policy:Policy,Entries:not null},"当主交代の原本がありません");long rev=0,at=0;var ids=new HashSet<EntityId>();foreach(var e in w.Succession.Entries){Need(e.Revision>rev&&e.Revision<=w.CommitSequence&&e.At>=at&&e.At<=w.ElapsedSeconds&&ids.Add(e.Input.Id)&&!FactionStances.OtherIdUsed(w,e.Input.Id,includeHouseSuccession:false)&&!FactionStances.OwnIdUsed(w,e.Input.Id),"当主原本の順序またはIDが不正です");Need(e==Prepare(w,e.Input,e.At,e.Revision,e.Input.Action==HouseSuccessionAction.Resolve),"同意・当主職・個別承継の原本が一致しません");rev=e.Revision;at=e.At;}Need(!Jobs(w).Any(j=>j.Cancelled==null&&j.Pending?.Due<=w.ElapsedSeconds),"予定された当主交代が未処理です");}
